def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if no_water_days >= 2 or hp <= 3:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    urgent_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 300:
            rich_count += 1
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            urgent_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 18
    loose_supply = supply >= 22

    if no_water_days >= 2:
        base = max(DAILY_SALARY * 1.25, highest_prev + 2.0, 95.0)
        if urgent_count >= 2:
            base += 8.0
        if tight_supply:
            base += 10.0
        return float(min(budget, base))

    if hp <= 3:
        base = max(DAILY_SALARY * 1.05, highest_prev * 0.92, 78.0)
        if tight_supply:
            base += 8.0
        return float(min(budget, base))

    if no_water_days == 1:
        if tight_supply:
            base = max(82.0, highest_prev * 0.82, avg_prev * 0.88)
            if urgent_count >= 1:
                base += 6.0
            return float(min(budget, base))
        if loose_supply:
            base = max(58.0, highest_prev * 0.58)
            return float(min(budget, base))
        base = max(68.0, highest_prev * 0.68)
        return float(min(budget, base))

    if highest_prev >= 125:
        if loose_supply:
            return float(min(budget, 24.0))
        return float(min(budget, 32.0))

    if highest_prev >= 100:
        if tight_supply:
            return float(min(budget, 48.0))
        return float(min(budget, 28.0))

    if avg_prev >= 80:
        return float(min(budget, 30.0 if loose_supply else 40.0))

    base = DAILY_SALARY * 0.42
    if rich_count >= 2:
        base -= 4.0
    if day >= 8:
        base += 6.0
    if tight_supply:
        base += 5.0
    return float(min(budget, max(18.0, base)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents are alive, spend enough to secure water.
    if not alive_opponents:
        target = min(budget, DAILY_SALARY * 0.6)
        return float(target)

    # Extract yesterday bids and also infer who is bidding aggressively.
    yesterday_bids = []
    yesterday_pressures = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                b = float(bid)
            except Exception:
                continue
            yesterday_bids.append(b)
            # Pressure proxy: high bid + still alive today implies strong willingness to pay.
            if opp.get('alive', False) and opp.get('hp', 0) > 0:
                yesterday_pressures.append(b)

    if not yesterday_bids:
        # Default conservative bid
        base = DAILY_SALARY * 0.55
        if hp <= 2:
            base = DAILY_SALARY * 0.9
        return float(min(budget, base))

    # Use top-1 and top-2 to slightly overbid the strongest threat.
    top1 = max(yesterday_bids)
    top2 = top1
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        top1 = sorted_b[0]
        top2 = sorted_b[1]

    # Detect if someone previously died (likely overbid/was outbid early).
    # If any opponent had yesterday hp_after <= 0, we can exploit by not matching their full spend.
    died_yesterday = False
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('hp_after', 1) <= 0:
            died_yesterday = True
            break

    # Supply-based aggressiveness: higher supply means less need to overbid.
    # supply is within [15,25].
    supply_ratio = 0.0
    try:
        supply_ratio = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    except Exception:
        supply_ratio = 0.5
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # If my hp is low, prioritize survival by bidding closer to top1.
    # Otherwise, bid just above top2/top1 depending on supply.
    if hp <= 2:
        bid_target = min(top1 * 1.03, DAILY_SALARY * 1.05)
    elif hp <= 4:
        bid_target = min(max(top2 * 1.02, top1 * 0.99), DAILY_SALARY * 0.95)
    else:
        # When supply is higher, we can undercut slightly; when lower, overbid slightly.
        undercut = 0.02 + 0.03 * (1.0 - supply_ratio)  # 0.02..0.05
        bid_target = min(top1 * (1.0 + undercut), DAILY_SALARY * (0.85 + 0.15 * supply_ratio))

    # Exploit if someone died yesterday: don't overpay as much.
    if died_yesterday:
        bid_target *= 0.95

    # Ensure we don't exceed budget.
    bid = min(float(budget), float(bid_target))

    # Also avoid bidding too low to secure water when hp is moderate.
    min_bid = 0.0
    if hp > 0:
        min_bid = DAILY_SALARY * (0.35 if supply_ratio > 0.6 else 0.45)
    if hp <= 4:
        min_bid = max(min_bid, DAILY_SALARY * 0.65)

    if bid < min_bid:
        bid = min(float(budget), float(min_bid))

    # Final cap: never bid more than what we can reasonably afford.
    if bid > budget:
        bid = float(budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        # No opponents, bid minimum to save budget
        return min(my_status['budget'], MY_DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = 0.0

    # Prioritize survival when HP is critical or consecutive no-water days
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        # Must win. Bid very aggressively, ensuring to outbid previous highest.
        base_bid = MY_DAILY_SALARY * 0.95
        if highest_prev_bid > 0:
            base_bid = max(base_bid, highest_prev_bid + 5) # Bid a bit higher to secure win

    elif my_status['hp'] <= 5:
        # Risky state: Strong need for water. Be aggressive but consider budget.
        # If opponents are extremely aggressive and my budget is low, might save for next day.
        if my_status['budget'] < MY_DAILY_SALARY * 0.8 and highest_prev_bid > MY_DAILY_SALARY * 0.8:
            base_bid = MY_DAILY_SALARY * 0.3 # Temporarily back off if budget is low and competition is fierce
        else:
            base_bid = MY_DAILY_SALARY * 0.75
            if highest_prev_bid > 0:
                base_bid = max(base_bid, highest_prev_bid + 3)

    else: # Normal HP
        # Good HP, can afford to be strategic.
        # If opponents are overbidding significantly, consider saving budget.
        if highest_prev_bid > MY_DAILY_SALARY * 0.8 and my_status['hp'] > 7:
            base_bid = MY_DAILY_SALARY * 0.3 # Let others fight, save budget
        else:
            # Normal competitive bid, adjusted by day progression
            if day_context['day'] < int(EPISODE_DAYS / 2):
                # Early game: slightly more conservative
                base_bid = MY_DAILY_SALARY * 0.5
                if highest_prev_bid > 0:
                    base_bid = max(base_bid, highest_prev_bid + 1)
            else:
                # Late game: competition might intensify, or some opponents might be weak.
                base_bid = MY_DAILY_SALARY * 0.6
                if highest_prev_bid > 0:
                    base_bid = max(base_bid, highest_prev_bid + 2)

    # Ensure bid does not exceed budget and is non-negative
    final_bid = min(my_status['budget'], base_bid)
    return max(0.0, final_bid)

